script:
// Szinkronmotor – egyenárammal gerjesztett, hengeres forgórész
// Synchronous motor – DC-excited cylindrical rotor
//   M = 3·U_f·E₀ / (ωₛ·X_d) · sin δ  (+ a csillapító kalicka nyomatéka / + damper cage torque)
//   Ī = (Ū − Ē₀) / (jX_d)       δ: terhelési szög / load angle

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Szinkronmotor", en: "Synchronous motor"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.002);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(1);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("U",  {hu: "Vonali feszültség U", en: "Line voltage U"}, 100, 500, 400, 1, "V");
param("f",  {hu: "Frekvencia f", en: "Frequency f"}, 10, 100, 50, 1, "Hz");
param("p",  {hu: "Póluspárok száma p", en: "Pole pairs p"}, 1, 4, 2, 1, "");
param("E",  {hu: "Gerjesztés E₀ / U_f", en: "Excitation E₀ / U_ph"}, 0.3, 2, 1.1, 0.01, "");
param("Xd", {hu: "Szinkron reaktancia X_d (50 Hz)", en: "Synchronous reactance X_d (50 Hz)"}, 1, 30, 8, 0.1, "Ω");
param("ML", {hu: "Terhelőnyomaték M_t", en: "Load torque M_L"}, 0, 200, 60, 1, "N·m");
param("D",  {hu: "Csillapítás (csillapító kalicka)", en: "Damping (damper cage)"}, 0, 20, 3, 0.1, "N·m·s");
param("J",  {hu: "Tehetetlenségi nyomaték J", en: "Moment of inertia J"}, 0.02, 1, 0.1, 0.01, "kg·m²");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("vec", {hu: "Mágneses mezővektorok", en: "Magnetic field vectors"}, true);
toggle("ph",  {hu: "Fázorábra", en: "Phasor diagram"}, true);
// Ezek változásakor a jelenet újraindul / The scene restarts when these change
resetOn("p");
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Újraszinkronozás", en: "Resynchronise"}, reset);

const PH = [C.L1, C.L2, C.L3];
const sx = 300, sy = 320;

// Gépadatok a csúszkákból; X a frekvenciával arányos / machine data from the sliders; X scales with f
function model() {
  const ws = 2 * PI * P.f / P.p, kf = P.f / 50;
  const Uf = P.U / sqrt(3), E0 = P.E * Uf, X = P.Xd * kf;
  return {ws, Uf, E0, X, Mmax: 3 * Uf * E0 / (ws * X)};
}

// Indulás szinkron fordulatszámon, a terheléshez illő δ-val / start in sync with the matching load angle
let th = 0;
const m0 = model();
const d0 = asin(clamp(P.ML / m0.Mmax, -1, 1));
let thm = (th - PI - d0) / P.p;   // forgórész mechanikai szöge / rotor mechanical angle
let wm = m0.ws;
// A forgórész É-i pólusa a hálózati eredő mező mögött δ-val jár / the rotor's N pole lags the network field by δ
const loadAngle = () => wrap(th - PI - P.p * thm);

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  // 10 allépés a pontosabb integráláshoz / 10 sub-steps for accuracy
  const n = 10, h = dt / n;
  for (let k = 0; k < n; k++) {
    const m = model(), d = loadAngle();
    // Szinkronozó nyomaték + a csillapító kalicka nyomatéka / synchronising torque + damper-cage torque
    const M = m.Mmax * sin(d) + P.D * (m.ws - wm);
    let Ml = P.ML;
    if (wm < 0.01 && M < Ml) Ml = max(M, 0);   // nem fordul vissza / does not run backwards
    wm = max(0, wm + (M - Ml) / P.J * h);
    thm += wm * h;
    th += 2 * PI * P.f * h;
  }
});

// Nyomatéknyilak: 200 px = billenőnyomaték; a Jelölők fülön is szerkeszthetők
// Torque arrows: 200 px = pull-out torque; also editable on the Markup tab
boundArrow("M-nyíl", {
  x: 620, y: 150, angle: 0,                      // kezdőpont, irány: jobbra / start point, direction: right
  length: "200 * M / Mmax",                      // hossz px-ben / length in px
  width: 4, color: "#d64045",
  label: "M = {M:0} N·m"                         // {M:0}: M értéke egészre kerekítve / value of M, rounded
});
boundArrow("Mt-nyíl", {
  x: 620, y: 182, angle: 0,
  length: "200 * ML / Mmax",
  width: 4, color: "#e8862a",
  label: "Mt"
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const m = model(), d = loadAngle();
  // Fázorok: Ū, Ē₀ = E₀∠−δ, Ī = (Ū − Ē₀)/(jX) / phasors
  const U = complex(m.Uf, 0), E = cpolar(m.E0, -d);
  const I = U.sub(E).div(complex(0, m.X));
  const axes = [0, deg(120), deg(240)];
  const ia = phases(sqrt(2) * I.abs(), th, I.arg());
  // Háromfázisú állórész; a vezetőkben ⊙/⊗ az áram iránya / Three-phase stator; ⊙/⊗ shows the current direction
  stator3(sx, sy, {p: P.p, i: ia, imax: sqrt(2) * max(I.abs(), 1e-9), axes: axes});

  // Forgórész: 2p pólus, felváltva É és D / rotor: 2p poles, alternating N and S
  circle(sx, sy, 160, {fill: "#c9ced6", stroke: "#9aa3b1", lw: 1.5});
  for (let j = 0; j < 2 * P.p; j++) {
    const a = thm + j * PI / P.p, N = j % 2 === 0;
    const px = sx + 112 * cos(a), py = sy - 112 * sin(a);
    box(px, py, 72, min(110, 280 / P.p), -a, {fill: N ? C.N : C.S, radius: 6});
    text(N ? "N" : "S", px, py + 7, {size: 20, bold: true, color: "#fff", align: "center"});
  }
  circle(sx, sy, 30, {fill: "#9aa3b1"});

  // A hálózati eredő mező tengelye és a δ szög / network field axis and the load angle δ
  const fa = (th - PI) / P.p;
  line(sx, sy, sx + 170 * cos(fa), sy - 170 * sin(fa), {stroke: C.red, lw: 1.5, dash: [6, 5]});
  const s1 = -thm, s2 = -(thm + d / P.p);   // képernyőszögek / screen angles
  arc(sx, sy, 58, min(s1, s2), max(s1, s2), {stroke: C.ink, lw: 2});
  const am = thm + d / (2 * P.p);
  text("δ", sx + 74 * cos(am), sy - 74 * sin(am) + 6, {size: 18, italic: true, bold: true, align: "center"});

  if (P.vec) {
    const B1 = fieldVec(ia, axes);                         // állórész / stator
    const ifq = 1.5 * sqrt(2) * m.E0 / m.X;                // gerjesztés áram-egyenértéke / excitation as equivalent current
    const ra = th - PI - d;                                // = p·thm, a forgórész tengelye / rotor axis
    const B2 = {x: ifq * cos(ra), y: ifq * sin(ra)};
    const Bd = {x: B1.x + B2.x, y: B1.y + B2.y};
    const mags = [B1.mag, hypot(B2.x, B2.y), hypot(Bd.x, Bd.y)];
    const k = 140 / max(...mags, 1e-9);
    for (let j = 0; j < P.p; j++) {
      const off = 2 * PI * j / P.p, lab = j === 0;
      phasor(sx, sy, mags[0] * k, (B1.angle + off) / P.p, {stroke: C.blue, lw: 3}, lab ? "B₁" : "");
      phasor(sx, sy, mags[1] * k, (atan2(B2.y, B2.x) + off) / P.p, {stroke: C.copper, lw: 3}, lab ? "B₂" : "");
      phasor(sx, sy, mags[2] * k, (atan2(Bd.y, Bd.x) + off) / P.p, {stroke: C.red, lw: 4}, lab ? "Bδ" : "");
    }
  }
  circle(sx, sy, 7, {fill: C.ink});

  // ── Fázorábra egy fázisra (Ū függőleges) / phasor diagram for one phase (Ū vertical) ──
  if (P.ph) {
    const ox = 760, oy = 470, ku = 170 / max(m.Uf, m.E0), up = PI / 2;
    text({hu: "Fázorábra (1 fázis)", en: "Phasor diagram (one phase)"}, 600, 100, {size: 14, color: C.gray});
    phasor(ox, oy, m.Uf * ku, up, {stroke: C.ink, lw: 3}, "U");
    phasor(ox, oy, m.E0 * ku, E.arg() + up, {stroke: C.copper, lw: 3}, "E₀");
    const jXI = U.sub(E);
    const ex = ox + m.E0 * ku * cos(E.arg() + up), ey = oy - m.E0 * ku * sin(E.arg() + up);
    phasor(ex, ey, jXI.abs() * ku, jXI.arg() + up, {stroke: C.purple, lw: 2, dash: [6, 4]}, "jX·I");
    const ki = 110 / (m.Uf / m.X);
    phasor(ox, oy, min(200, I.abs() * ki), I.arg() + up, {stroke: C.blue, lw: 2.5}, "I");
    arc(ox, oy, 46, min(-up, d - up), max(-up, d - up), {stroke: C.ink, lw: 1.5});
    circle(ox, oy, 4, {fill: C.ink});
  }

  // ── Mért értékek / readouts ──
  const ns = 60 * P.f / P.p, n = wm * 30 / PI;
  const S = U.mul(I.conj()).scale(3);                 // P + jQ felvett / consumed
  const inSync = abs(wm - m.ws) < 0.02 * m.ws;
  const Me = m.Mmax * sin(d) + P.D * (m.ws - wm);
  val({M: Me, Mmax: m.Mmax, ML: P.ML, delta: todeg(d), E0: m.E0, Uf: m.Uf, I: I.abs(), n: n});   // a Jelölők fülnek / for the Markup tab
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Állapot", en: "State"}, tr(inSync ? {hu: "szinkronban", en: "in synchronism"} : {hu: "KIESETT a szinkronizmusból", en: "OUT OF STEP"}), "");
  show({hu: "Szinkron fordulatszám nₛ", en: "Synchronous speed nₛ"}, ns, "1/min");
  show({hu: "Fordulatszám n", en: "Speed n"}, n, "1/min");
  show({hu: "Terhelési szög δ", en: "Load angle δ"}, todeg(d), "°");
  show({hu: "Nyomaték M", en: "Torque M"}, Me, "N·m");
  show({hu: "Billenőnyomaték M_max (δ = 90°)", en: "Pull-out torque M_max (δ = 90°)"}, m.Mmax, "N·m");
  show({hu: "Állórészáram I", en: "Stator current I"}, I.abs(), "A");
  show("cos φ", S.re / max(S.abs(), 1e-9), "");
  show({hu: "Jelleg", en: "Character"}, tr(S.im > 0.02 * S.abs() ? {hu: "induktív – alulgerjesztett", en: "inductive – under-excited"}
       : S.im < -0.02 * S.abs() ? {hu: "kapacitív – túlgerjesztett", en: "capacitive – over-excited"} : {hu: "ohmos (cos φ ≈ 1)", en: "resistive (cos φ ≈ 1)"}), "");
  show({hu: "Hatásos teljesítmény P", en: "Active power P"}, S.re, "W");
  show({hu: "Meddő teljesítmény Q", en: "Reactive power Q"}, S.im, "var");

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Terhelési szög δ", en: "Load angle δ"}, todeg(d), {unit: "°", color: C.purple});
  for (let j = 0; j < 3; j++) plot("i" + "₁₂₃"[j], ia[j], {unit: "A", color: PH[j], group: "i"});
  plot({hu: "Fordulatszám n", en: "Speed n"}, n, {unit: "1/min", color: C.blue});
});
